package forth

import (
	"fmt"
	"strconv"
	"strings"
)

// interp is a single Forth evaluation context: a value stack plus a
// dictionary of words. Each word is a function that operates on the
// interpreter, so user-defined words are simply sequences of such
// functions captured at definition time (giving lexical scoping).
type interp struct {
	stack []int
	dict  map[string]func(*interp) error
}

func newInterp() *interp {
	f := &interp{
		stack: []int{},
		dict:  make(map[string]func(*interp) error),
	}
	f.dict["+"] = f.add
	f.dict["-"] = f.sub
	f.dict["*"] = f.mul
	f.dict["/"] = f.div
	f.dict["dup"] = f.dup
	f.dict["drop"] = f.drop
	f.dict["swap"] = f.swap
	f.dict["over"] = f.over
	return f
}

// Forth evaluates each input line in order, sharing one interpreter so
// that word definitions persist across lines.
func Forth(input []string) ([]int, error) {
	f := newInterp()
	for _, line := range input {
		tokens := strings.Fields(line)
		for i := 0; i < len(tokens); i++ {
			tok := tokens[i]
			switch {
			case tok == ":":
				if err := f.define(tokens[i+1:]); err != nil {
					return nil, err
				}
				i += f.defineConsume(tokens[i+1:])
			case isNumber(tok):
				n, _ := strconv.Atoi(tok)
				f.push(n)
			default:
				op, ok := f.dict[strings.ToLower(tok)]
				if !ok {
					return nil, fmt.Errorf("undefined operation: %s", tok)
				}
				if err := op(f); err != nil {
					return nil, err
				}
			}
		}
	}
	return f.stack, nil
}

// define parses a definition of the form `name body... ;` from tokens
// (which start at the name) and registers the new word. It returns the
// number of tokens consumed so the caller can advance past the `;`.
func (f *interp) define(tokens []string) error {
	if len(tokens) == 0 {
		return fmt.Errorf("incomplete definition")
	}
	name := strings.ToLower(tokens[0])
	if isNumber(name) {
		return fmt.Errorf("illegal operation: cannot redefine a number")
	}
	body := tokens[1:]
	for i, t := range body {
		if t == ";" {
			body = body[:i]
			break
		}
	}
	ops, err := f.compile(body)
	if err != nil {
		return err
	}
	f.dict[name] = func(ff *interp) error {
		for _, op := range ops {
			if err := op(ff); err != nil {
				return err
			}
		}
		return nil
	}
	return nil
}

// defineConsume reports how many tokens a definition occupies, including
// the terminating `;`.
func (f *interp) defineConsume(tokens []string) int {
	for i, t := range tokens {
		if t == ";" {
			return i + 2 // name + body + ';'
		}
	}
	return len(tokens) + 1
}

// compile resolves each body token into an operation. Number tokens push
// a constant; word tokens are looked up in the dictionary right now so
// that a definition captures the meaning of its words at definition time.
func (f *interp) compile(body []string) ([]func(*interp) error, error) {
	ops := make([]func(*interp) error, 0, len(body))
	for _, tok := range body {
		if isNumber(tok) {
			n, _ := strconv.Atoi(tok)
			ops = append(ops, func(ff *interp) error {
				ff.push(n)
				return nil
			})
			continue
		}
		name := strings.ToLower(tok)
		op, ok := f.dict[name]
		if !ok {
			ops = append(ops, func(ff *interp) error {
				return fmt.Errorf("undefined operation: %s", name)
			})
			continue
		}
		ops = append(ops, op)
	}
	return ops, nil
}

// isNumber reports whether tok is a (possibly negative) integer literal.
func isNumber(tok string) bool {
	s := tok
	if strings.HasPrefix(s, "-") {
		s = s[1:]
	}
	if s == "" {
		return false
	}
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func (f *interp) push(n int) {
	f.stack = append(f.stack, n)
}

func (f *interp) pop() (int, error) {
	if len(f.stack) == 0 {
		return 0, fmt.Errorf("empty stack")
	}
	n := f.stack[len(f.stack)-1]
	f.stack = f.stack[:len(f.stack)-1]
	return n, nil
}

func (f *interp) add() error {
	b, err := f.pop()
	if err != nil {
		return err
	}
	a, err := f.pop()
	if err != nil {
		return err
	}
	f.push(a + b)
	return nil
}

func (f *interp) sub() error {
	b, err := f.pop()
	if err != nil {
		return err
	}
	a, err := f.pop()
	if err != nil {
		return err
	}
	f.push(a - b)
	return nil
}

func (f *interp) mul() error {
	b, err := f.pop()
	if err != nil {
		return err
	}
	a, err := f.pop()
	if err != nil {
		return err
	}
	f.push(a * b)
	return nil
}

func (f *interp) div() error {
	b, err := f.pop()
	if err != nil {
		return err
	}
	a, err := f.pop()
	if err != nil {
		return err
	}
	if b == 0 {
		return fmt.Errorf("divide by zero")
	}
	f.push(a / b)
	return nil
}

func (f *interp) dup() error {
	if len(f.stack) == 0 {
		return fmt.Errorf("empty stack")
	}
	f.push(f.stack[len(f.stack)-1])
	return nil
}

func (f *interp) drop() error {
	if len(f.stack) == 0 {
		return fmt.Errorf("empty stack")
	}
	f.stack = f.stack[:len(f.stack)-1]
	return nil
}

func (f *interp) swap() error {
	if len(f.stack) < 2 {
		return fmt.Errorf("stack underflow")
	}
	n := len(f.stack)
	f.stack[n-1], f.stack[n-2] = f.stack[n-2], f.stack[n-1]
	return nil
}

func (f *interp) over() error {
	if len(f.stack) < 2 {
		return fmt.Errorf("stack underflow")
	}
	f.push(f.stack[len(f.stack)-2])
	return nil
}

